{#- Code generated by packages/kit-compose/src/server-organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
    Source: packages/compose-gen/specs/organisms/bento-grid.json
    Tiles of different sizes in one grid: the large and wide tiles hold the important features. Sizes come from the data (large, wide, small). Axes: layout (bento, even: all tiles alike), media (none, image: a picture in the large tiles), tone, density.
    Props (p): id, title, tiles, empty, layout, media, tone, density, landmarkLabel. -#}
{%- set k_SPAN = {'large': 'md:col-span-2 md:row-span-2', 'wide': 'md:col-span-2', 'small': ''} -%}
{%- set v_id = (p.id ?? null) -%}
{%- set v_title = (p.title ?? null) -%}
{%- set v_tiles = (p.tiles ?? null) -%}
{%- set v_empty = (p.empty ?? '') -%}
{%- set v_layout = (p.layout ?? 'bento') -%}
{%- set v_media = (p.media ?? 'none') -%}
{%- set v_tone = (p.tone ?? 'default') -%}
{%- set v_density = (p.density ?? 'default') -%}
{%- set v_landmarkLabel = (p.landmarkLabel ?? null) -%}
{%- set c_6 -%}
  {%- if og_t(og_eq(og_len(v_tiles), 0)) %}
    {{ include('blocks/empty-state.html.twig', {'p': {'icon': 'layout-dashboard', 'title': v_empty}}, with_context = false) }}
  {%- else %}
    {%- set c_5 -%}
      {%- for v_tile in og_l(v_tiles) %}
        {%- set c_4 -%}
          {%- set c_3 -%}
            {{ include('icons/LucideIcon.html.twig', {'name': og_s(og_get(v_tile, ['icon'])), 'size': 24}, with_context = false) }}
            {%- set c_1 -%}
              {{ og_text(og_get(v_tile, ['title'])) }}
            {%- endset -%}
            {{ include('compose/Title.html.twig', {'as': 3, 'size': 'xl', 'weight': 'bold', 'children': c_1}, with_context = false) }}
            {%- set c_2 -%}
              {{ og_text(og_get(v_tile, ['text'])) }}
            {%- endset -%}
            {{ include('compose/Text.html.twig', {'size': 'sm', 'class': 'text-muted-foreground', 'children': c_2}, with_context = false) }}
            {%- if og_t(og_and([og_eq(v_media, 'image'), og_or([og_eq(og_get(v_tile, ['size']), 'large'), og_eq(v_layout, 'even')])])) %}
              {{ include('blocks/media-frame.html.twig', {'p': {'alt': og_get(v_tile, ['title']), 'ratio': '4/3', 'className': og_cnv(['mt-auto'])}}, with_context = false) }}
            {%- endif %}
          {%- endset -%}
          {{ include('compose/CardContent.html.twig', {'class': 'flex h-full flex-col gap-4', 'children': c_3}, with_context = false) }}
        {%- endset -%}
        {{ include('compose/Card.html.twig', {'variant': 'default', 'class': og_s(og_cnv(['h-full overflow-hidden', (og_t(og_eq(v_density, 'compact')) ? 'gap-4 p-4' : ''), (og_t(og_eq(v_layout, 'bento')) ? og_at(k_SPAN, og_get(v_tile, ['size'])) : '')])), 'attrs': og_attrs(['data-size', (og_t(og_eq(v_layout, 'bento')) ? og_get(v_tile, ['size']) : 'even')]), 'children': c_4}, with_context = false) }}
      {%- endfor %}
    {%- endset -%}
    {{ include('compose/Grid.html.twig', {'cols': '1-4', 'class': 'auto-rows-fr gap-4', 'attrs': og_attrs(['data-slot', 'items']), 'children': c_5}, with_context = false) }}
  {%- endif %}
{%- endset -%}
{{ include('blocks/section-frame.html.twig', {'p': {'id': v_id, 'title': v_title, 'tone': v_tone, 'density': v_density, 'landmarkLabel': v_landmarkLabel}, 'children': og_markup(c_6)}, with_context = false) }}
